+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+
+namespace ContosoUniversity.Tests.Services;
+
+public class NotificationServiceTests : IDisposable
+{
+    private readonly NotificationService _service;
+
+    public NotificationServiceTests()
+    {
+        _service = new NotificationService();
+        // Drain any existing notifications from the static queue
+        while (_service.ReceiveNotification() != null) { }
+    }
+
+    public void Dispose()
+    {
+        _service.Dispose();
+    }
+
+    [Fact]
+    public void SendNotification_WithDisplayName_CreatesCorrectMessage()
+    {
+        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("Student", notification.EntityType);
+        Assert.Equal("1", notification.EntityId);
+        Assert.Equal("CREATE", notification.Operation);
+        Assert.Contains("John Doe", notification.Message);
+        Assert.Contains("created", notification.Message);
+        Assert.Equal("Admin", notification.CreatedBy);
+        Assert.False(notification.IsRead);
+    }
+
+    [Fact]
+    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
+    {
+        _service.SendNotification("Course", "42", EntityOperation.UPDATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("ID: 42", notification.Message);
+        Assert.Contains("updated", notification.Message);
+    }
+
+    [Fact]
+    public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
+    {
+        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "System");
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("deleted", notification.Message);
+        Assert.Contains("Engineering", notification.Message);
+        Assert.Equal("DELETE", notification.Operation);
+    }
+
+    [Fact]
+    public void SendNotification_NullUserName_DefaultsToSystem()
+    {
+        _service.SendNotification("Student", "1", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("System", notification.CreatedBy);
+    }
+
+    [Fact]
+    public void ReceiveNotification_EmptyQueue_ReturnsNull()
+    {
+        var notification = _service.ReceiveNotification();
+
+        Assert.Null(notification);
+    }
+
+    [Fact]
+    public void SendAndReceive_MultipleNotifications_ReturnsFIFO()
+    {
+        _service.SendNotification("A", "1", EntityOperation.CREATE);
+        _service.SendNotification("B", "2", EntityOperation.UPDATE);
+        _service.SendNotification("C", "3", EntityOperation.DELETE);
+
+        var first = _service.ReceiveNotification();
+        var second = _service.ReceiveNotification();
+        var third = _service.ReceiveNotification();
+        var fourth = _service.ReceiveNotification();
+
+        Assert.NotNull(first);
+        Assert.Equal("A", first.EntityType);
+        Assert.NotNull(second);
+        Assert.Equal("B", second.EntityType);
+        Assert.NotNull(third);
+        Assert.Equal("C", third.EntityType);
+        Assert.Null(fourth);
+    }
+
+    [Fact]
+    public void SendNotification_SetsCreatedAtToCurrentTime()
+    {
+        var before = DateTime.Now;
+        _service.SendNotification("Student", "1", EntityOperation.CREATE);
+        var after = DateTime.Now;
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.True(notification.CreatedAt >= before.AddSeconds(-1));
+        Assert.True(notification.CreatedAt <= after.AddSeconds(1));
+    }
+
+    [Fact]
+    public void MarkAsRead_DoesNotThrow()
+    {
+        // MarkAsRead is a no-op for in-memory implementation, but should not throw
+        var exception = Record.Exception(() => _service.MarkAsRead(1));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void MarkAsRead_WithInvalidId_DoesNotThrow()
+    {
+        var exception = Record.Exception(() => _service.MarkAsRead(-1));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void Dispose_CanBeCalledMultipleTimes()
+    {
+        var service = new NotificationService();
+        var exception = Record.Exception(() =>
+        {
+            service.Dispose();
+            service.Dispose();
+        });
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void SendNotification_CreateOperation_MessageContainsNewAndCreated()
+    {
+        _service.SendNotification("Student", "1", "Jane Smith", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.StartsWith("New ", notification.Message);
+        Assert.Contains("created", notification.Message);
+    }
+
+    [Fact]
+    public void SendNotification_UpdateOperation_MessageContainsUpdated()
+    {
+        _service.SendNotification("Course", "1", "Chemistry", EntityOperation.UPDATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("updated", notification.Message);
+        Assert.Contains("Chemistry", notification.Message);
+    }
+
+    [Fact]
+    public void SendNotification_WithEmptyDisplayName_UsesEntityId()
+    {
+        _service.SendNotification("Student", "42", "", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("ID: 42", notification.Message);
+    }
+
+    [Fact]
+    public void SendNotification_WithWhitespaceDisplayName_UsesEntityId()
+    {
+        _service.SendNotification("Student", "42", "   ", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("ID: 42", notification.Message);
+    }
+}
