+namespace ContosoUniversity.Tests;
+
+public class PaginatedListTests
+{
+    [Fact]
+    public void Constructor_SetsPageIndexAndTotalPages()
+    {
+        var items = new List<string> { "a", "b", "c" };
+
+        var list = new PaginatedList<string>(items, 10, 2, 3);
+
+        Assert.Equal(2, list.PageIndex);
+        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
+        Assert.Equal(3, list.Count);
+    }
+
+    [Fact]
+    public void Constructor_AddsAllItemsToList()
+    {
+        var items = new List<int> { 1, 2, 3, 4, 5 };
+
+        var list = new PaginatedList<int>(items, 20, 1, 5);
+
+        Assert.Equal(5, list.Count);
+        Assert.Contains(1, list);
+        Assert.Contains(5, list);
+    }
+
+    [Fact]
+    public void HasPreviousPage_FirstPage_ReturnsFalse()
+    {
+        var list = new PaginatedList<string>(new List<string> { "a" }, 10, 1, 5);
+
+        Assert.False(list.HasPreviousPage);
+    }
+
+    [Fact]
+    public void HasPreviousPage_SecondPage_ReturnsTrue()
+    {
+        var list = new PaginatedList<string>(new List<string> { "a" }, 10, 2, 5);
+
+        Assert.True(list.HasPreviousPage);
+    }
+
+    [Fact]
+    public void HasNextPage_LastPage_ReturnsFalse()
+    {
+        var list = new PaginatedList<string>(new List<string> { "a" }, 5, 5, 1);
+
+        Assert.False(list.HasNextPage);
+    }
+
+    [Fact]
+    public void HasNextPage_FirstPageOfMany_ReturnsTrue()
+    {
+        var list = new PaginatedList<string>(new List<string> { "a" }, 10, 1, 5);
+
+        Assert.True(list.HasNextPage);
+    }
+
+    [Fact]
+    public void TotalPages_CalculatedFromCountAndPageSize()
+    {
+        // 7 items, page size 3 => ceil(7/3) = 3 pages
+        var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, 7, 1, 3);
+
+        Assert.Equal(3, list.TotalPages);
+    }
+
+    [Fact]
+    public void TotalPages_ExactDivision_NoExtraPage()
+    {
+        // 10 items, page size 5 => 2 pages exactly
+        var list = new PaginatedList<int>(new List<int> { 1, 2, 3, 4, 5 }, 10, 1, 5);
+
+        Assert.Equal(2, list.TotalPages);
+    }
+
+    [Fact]
+    public void TotalPages_SingleItem_OnePage()
+    {
+        var list = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
+
+        Assert.Equal(1, list.TotalPages);
+    }
+
+    [Fact]
+    public void Create_ReturnsCorrectPage()
+    {
+        var source = Enumerable.Range(1, 20).AsQueryable();
+
+        var result = PaginatedList<int>.Create(source, 2, 5);
+
+        Assert.Equal(2, result.PageIndex);
+        Assert.Equal(4, result.TotalPages); // ceil(20/5) = 4
+        Assert.Equal(5, result.Count);
+        Assert.Equal(6, result[0]); // Second page starts at item 6
+        Assert.Equal(10, result[4]); // Second page ends at item 10
+    }
+
+    [Fact]
+    public void Create_FirstPage_ReturnsFirstItems()
+    {
+        var source = Enumerable.Range(1, 15).AsQueryable();
+
+        var result = PaginatedList<int>.Create(source, 1, 5);
+
+        Assert.Equal(1, result.PageIndex);
+        Assert.Equal(1, result[0]);
+        Assert.Equal(5, result[4]);
+    }
+
+    [Fact]
+    public void Create_LastPage_ReturnsRemainingItems()
+    {
+        var source = Enumerable.Range(1, 7).AsQueryable();
+
+        var result = PaginatedList<int>.Create(source, 2, 5);
+
+        Assert.Equal(2, result.PageIndex);
+        Assert.Equal(2, result.Count); // 7 - 5 = 2 items on page 2
+        Assert.Equal(6, result[0]);
+        Assert.Equal(7, result[1]);
+    }
+
+    [Fact]
+    public void HasPreviousPage_PageThree_ReturnsTrue()
+    {
+        var list = new PaginatedList<int>(new List<int> { 1 }, 30, 3, 10);
+
+        Assert.True(list.HasPreviousPage);
+    }
+
+    [Fact]
+    public void HasNextPage_MiddlePage_ReturnsTrue()
+    {
+        var list = new PaginatedList<int>(new List<int> { 1 }, 30, 2, 10);
+
+        Assert.True(list.HasNextPage);
+    }
+
+    [Fact]
+    public void Constructor_EmptyItems_CreatesEmptyList()
+    {
+        var list = new PaginatedList<string>(new List<string>(), 0, 1, 10);
+
+        Assert.Empty(list);
+        Assert.Equal(1, list.PageIndex);
+        Assert.Equal(0, list.TotalPages);
+    }
+}
