using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

/// <summary>
/// Tests for NotificationService. Because the underlying ConcurrentQueue is static
/// and shared across all test classes (controller tests also enqueue via BaseController),
/// each test creates its own service instance and drains the queue before asserting.
/// Tests that verify receive behavior send-then-receive within the same test to avoid
/// cross-test ordering issues.
/// </summary>
public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Best-effort drain of the shared queue
        DrainQueue();
    }

    public void Dispose()
    {
        _service.Dispose();
    }

    private void DrainQueue()
    {
        // Drain any stale notifications from the shared static queue
        while (_service.ReceiveNotification() != null) { }
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage()
    {
        DrainQueue();
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        DrainQueue();
        _service.SendNotification("Course", "42", EntityOperation.UPDATE);

        var notification = FindNotification("Course", "42");

        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
    {
        DrainQueue();
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "System");

        var notification = FindNotification("Department", "5");

        Assert.NotNull(notification);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Engineering", notification.Message);
        Assert.Equal("DELETE", notification.Operation);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        DrainQueue();
        _service.SendNotification("Student", "99", EntityOperation.CREATE);

        var notification = FindNotification("Student", "99");

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        DrainQueue();

        var notification = _service.ReceiveNotification();

        Assert.Null(notification);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_ReturnsFIFO()
    {
        DrainQueue();
        // Use unique entity IDs to distinguish from other test pollution
        _service.SendNotification("TypeA", "fifo-1", EntityOperation.CREATE);
        _service.SendNotification("TypeB", "fifo-2", EntityOperation.UPDATE);
        _service.SendNotification("TypeC", "fifo-3", EntityOperation.DELETE);

        var received = new List<Notification>();
        Notification? n;
        while ((n = _service.ReceiveNotification()) != null)
        {
            received.Add(n);
        }

        // The three we sent should appear in FIFO order (there may be extras from other tests)
        var ours = received.Where(r => r.EntityId.StartsWith("fifo-")).ToList();
        Assert.Equal(3, ours.Count);
        Assert.Equal("TypeA", ours[0].EntityType);
        Assert.Equal("TypeB", ours[1].EntityType);
        Assert.Equal("TypeC", ours[2].EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        DrainQueue();
        var before = DateTime.Now;
        _service.SendNotification("Student", "time-test", EntityOperation.CREATE);
        var after = DateTime.Now;

        var notification = FindNotification("Student", "time-test");

        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before.AddSeconds(-1));
        Assert.True(notification.CreatedAt <= after.AddSeconds(1));
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var exception = Record.Exception(() => _service.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void MarkAsRead_WithInvalidId_DoesNotThrow()
    {
        var exception = Record.Exception(() => _service.MarkAsRead(-1));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_CanBeCalledMultipleTimes()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() =>
        {
            service.Dispose();
            service.Dispose();
        });
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_CreateOperation_MessageContainsNewAndCreated()
    {
        DrainQueue();
        _service.SendNotification("Student", "create-msg", "Jane Smith", EntityOperation.CREATE);

        var notification = FindNotification("Student", "create-msg");

        Assert.NotNull(notification);
        Assert.StartsWith("New ", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsUpdated()
    {
        DrainQueue();
        _service.SendNotification("Course", "upd-msg", "Chemistry", EntityOperation.UPDATE);

        var notification = FindNotification("Course", "upd-msg");

        Assert.NotNull(notification);
        Assert.Contains("updated", notification.Message);
        Assert.Contains("Chemistry", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesEntityId()
    {
        DrainQueue();
        _service.SendNotification("Student", "empty-dn", "", EntityOperation.CREATE);

        var notification = FindNotification("Student", "empty-dn");

        Assert.NotNull(notification);
        Assert.Contains("ID: empty-dn", notification.Message);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesEntityId()
    {
        DrainQueue();
        _service.SendNotification("Student", "ws-dn", "   ", EntityOperation.CREATE);

        var notification = FindNotification("Student", "ws-dn");

        Assert.NotNull(notification);
        Assert.Contains("ID: ws-dn", notification.Message);
    }

    /// <summary>
    /// Drains the queue and returns the first notification matching entity type + id.
    /// </summary>
    private Notification? FindNotification(string entityType, string entityId)
    {
        Notification? target = null;
        Notification? n;
        while ((n = _service.ReceiveNotification()) != null)
        {
            if (n.EntityType == entityType && n.EntityId == entityId && target == null)
                target = n;
        }
        return target;
    }
}

